2697: BIF_RETTYPE send_3(BIF_ALIST_3)
2698: {
2699:     BIF_RETTYPE retval;
2700:     Eterm ref;
2701:     Process *p = BIF_P;
2702:     Eterm to = BIF_ARG_1;
2703:     Eterm msg = BIF_ARG_2;
2704:     Eterm opts = BIF_ARG_3;
2705: 
2706:     Eterm l = opts;
2707:     Sint result;
2708:     int connect = 1, suspend = 1, prio = 0;
2709:     Eterm ctx;
2710: 
2711:     ERTS_MSACC_PUSH_STATE_M_X();
2712: 
2713:     while (is_list(l)) {
2714: 	if (CAR(list_val(l)) == am_noconnect) {
2715: 	    connect = 0;
2716: 	} else if (CAR(list_val(l)) == am_nosuspend) {
2717: 	    suspend = 0;
2718: 	} else if (CAR(list_val(l)) == am_priority) {
2719: 	    prio = !0;
2720: 	} else {
2721:             BIF_P->fvalue = am_badopt;
2722:             ERTS_BIF_PREP_ERROR(retval, p, BADARG | EXF_HAS_EXT_INFO);
2723: 	    goto done;
2724: 	}
2725: 	l = CDR(list_val(l));
2726:     }
2727:     if(!is_nil(l)) {
2728: 	BIF_P->fvalue = am_badopt;
2729: 	ERTS_BIF_PREP_ERROR(retval, p, BADARG | EXF_HAS_EXT_INFO);
2730: 	goto done;
2731:     }
2732: 
2733: #ifdef DEBUG
2734:     ref = NIL;
2735: #endif
2736: 
2737:     ERTS_MSACC_SET_STATE_CACHED_M_X(ERTS_MSACC_STATE_SEND);
2738:     result = do_send(p, to, msg, am_ok, &ref, &ctx, connect, suspend, prio);
2739:     ERTS_MSACC_POP_STATE_M_X();
2740: 
2741:     if (result >= 0) {
2742: 	ERTS_VBUMP_REDS(p, 4);
2743: 	if (ERTS_IS_PROC_OUT_OF_REDS(p))
2744: 	    goto yield_return;
2745: 	ERTS_BIF_PREP_RET(retval, am_ok);
2746: 	goto done;
2747:     }
2748: 
2749:     switch (result) {
2750:     case SEND_NOCONNECT:
2751: 	if (connect) {
2752: 	    ERTS_BIF_PREP_RET(retval, am_ok);
2753: 	} else {
2754: 	    ERTS_BIF_PREP_RET(retval, am_noconnect);
2755: 	}
2756: 	break;
2757:     case SEND_YIELD:
2758: 	if (suspend) {
2759: 	    ERTS_BIF_PREP_YIELD3(retval, BIF_TRAP_EXPORT(BIF_send_3), p, to, msg, opts);
2760: 	} else {
2761: 	    ERTS_BIF_PREP_RET(retval, am_nosuspend);
2762: 	}
2763: 	break;
2764:     case SEND_YIELD_RETURN:
2765: 	if (!suspend) {
2766: 	    ERTS_BIF_PREP_RET(retval, am_nosuspend);
2767: 	    break;
2768: 	}
2769:     yield_return:
2770: 	ERTS_BIF_PREP_YIELD_RETURN(retval, p, am_ok);
2771:         break;
2772:     case SEND_AWAIT_RESULT:
2773: 	ASSERT(is_internal_ordinary_ref(ref));
2774: 	ERTS_BIF_PREP_TRAP3(retval, await_port_send_result_trap, p, ref, am_nosuspend, am_ok);
2775: 	break;
2776:     case SEND_BADARG:
2777: 	ERTS_BIF_PREP_ERROR(retval, p, BADARG);
2778: 	break;
2779:     case SEND_SYSTEM_LIMIT:
2780: 	ERTS_BIF_PREP_ERROR(retval, p, SYSTEM_LIMIT);
2781: 	break;
2782:     case SEND_USER_ERROR:
2783: 	ERTS_BIF_PREP_ERROR(retval, p, EXC_ERROR);
2784: 	break;
2785:     case SEND_INTERNAL_ERROR:
2786: 	ERTS_BIF_PREP_ERROR(retval, p, EXC_INTERNAL_ERROR);
2787: 	break;
2788:     case SEND_YIELD_CONTINUE:
2789: 	BUMP_ALL_REDS(p);
2790: 	ERTS_BIF_PREP_TRAP1(retval, &dsend_continue_trap_export, p, ctx);
2791: 	break;
2792:     default:
2793: 	erts_exit(ERTS_ABORT_EXIT, "send_3 invalid result %d\n", (int)result);
2794: 	break;
2795:     }
2796: 
2797: done:
2798:     return retval;
2799: }
