2845: Eterm erl_send(Process *p, Eterm to, Eterm msg)
2846: {
2847:     Eterm retval;
2848:     Eterm ref;
2849:     Sint result;
2850:     Eterm ctx;
2851:     ERTS_MSACC_PUSH_AND_SET_STATE_M_X(ERTS_MSACC_STATE_SEND);
2852: 
2853: #ifdef DEBUG
2854:     ref = NIL;
2855: #endif
2856: 
2857:     result = do_send(p, to, msg, msg, &ref, &ctx, 1, 1, 0);
2858: 
2859:     ERTS_MSACC_POP_STATE_M_X();
2860: 
2861:     if (result >= 0) {
2862: 	ERTS_VBUMP_REDS(p, 4);
2863: 	if (ERTS_IS_PROC_OUT_OF_REDS(p))
2864: 	    goto yield_return;
2865: 	ERTS_BIF_PREP_RET(retval, msg);
2866: 	goto done;
2867:     }
2868: 
2869:     switch (result) {
2870:     case SEND_NOCONNECT:
2871: 	ERTS_BIF_PREP_RET(retval, msg);
2872: 	break;
2873:     case SEND_YIELD:
2874: 	ERTS_BIF_PREP_YIELD2(retval, BIF_TRAP_EXPORT(BIF_send_2), p, to, msg);
2875: 	break;
2876:     case SEND_YIELD_RETURN:
2877:     yield_return:
2878: 	ERTS_BIF_PREP_YIELD_RETURN(retval, p, msg);
2879:         break;
2880:     case SEND_AWAIT_RESULT:
2881: 	ASSERT(is_internal_ordinary_ref(ref));
2882: 	ERTS_BIF_PREP_TRAP3(retval,
2883: 			    await_port_send_result_trap, p, ref, msg, msg);
2884: 	break;
2885:     case SEND_BADARG:
2886: 	ERTS_BIF_PREP_ERROR(retval, p, BADARG);
2887: 	break;
2888:     case SEND_SYSTEM_LIMIT:
2889: 	ERTS_BIF_PREP_ERROR(retval, p, SYSTEM_LIMIT);
2890: 	break;
2891:     case SEND_USER_ERROR:
2892: 	ERTS_BIF_PREP_ERROR(retval, p, EXC_ERROR);
2893: 	break;
2894:     case SEND_INTERNAL_ERROR:
2895: 	ERTS_BIF_PREP_ERROR(retval, p, EXC_INTERNAL_ERROR);
2896: 	break;
2897:     case SEND_YIELD_CONTINUE:
2898: 	BUMP_ALL_REDS(p);
2899: 	ERTS_BIF_PREP_TRAP1(retval, &dsend_continue_trap_export, p, ctx);
2900: 	break;
2901:     default:
2902: 	erts_exit(ERTS_ABORT_EXIT, "invalid send result %d\n", (int)result);
2903: 	break;
2904:     }
2905: 
2906: done:
2907:     return retval;
2908: }
