1307: const Export *beam_jit_handle_unloaded_fun(Process *c_p,
1308:                                            Eterm *reg,
1309:                                            int arity,
1310:                                            Eterm fun_thing,
1311:                                            ErtsCodeIndex code_ix) {
1312:     const ErlFunEntry *fe;
1313:     const Export *ep;
1314:     Eterm module, args;
1315:     ErlFunThing *funp;
1316:     Module *modp;
1317: 
1318:     funp = (ErlFunThing *)fun_val(fun_thing);
1319:     ASSERT(is_local_fun(funp));
1320: 
1321:     fe = funp->entry.fun;
1322:     module = fe->module;
1323: 
1324:     ERTS_THR_READ_MEMORY_BARRIER;
1325: 
1326:     if (fe->pend_purge_address) {
1327:         /* The system is currently trying to purge the module containing this
1328:          * fun. Suspend the process and let it try again when the purge
1329:          * operation is done (may succeed or not). */
1330:         ep = erts_suspend_process_on_pending_purge_lambda(c_p, fe);
1331:     } else {
1332:         if ((modp = erts_get_module(module, code_ix)) != NULL &&
1333:             modp->curr.code_hdr != NULL) {
1334:             /* There is a module loaded, but obviously the fun is not defined
1335:              * in it. We must not call the error_handler (or we will get into
1336:              * an infinite loop). */
1337:             c_p->current = NULL;
1338:             c_p->freason = EXC_BADFUN;
1339:             c_p->fvalue = fun_thing;
1340:             return NULL;
1341:         }
1342: 
1343:         /* No current code for this module. Call the error_handler module to
1344:          * attempt loading the module. */
1345:         ep = erts_find_function(erts_proc_get_error_handler(c_p),
1346:                                 am_undefined_lambda,
1347:                                 3,
1348:                                 code_ix);
1349:         if (ERTS_UNLIKELY(ep == NULL)) {
1350:             /* No error handler, crash out. */
1351:             c_p->current = NULL;
1352:             c_p->freason = EXC_UNDEF;
1353:             return NULL;
1354:         }
1355:     }
1356: 
1357:     args = beam_jit_build_argument_list(c_p, reg, arity);
1358: 
1359:     reg[0] = module;
1360:     reg[1] = fun_thing;
1361:     reg[2] = args;
1362:     reg[3] = NIL;
1363: 
1364:     return ep;
